var legacyMonolithSymbolContracts = buildLegacySymbolContracts(legacyMonolithSymbolSeeds)

func legacyMonolithSymbolStats() map[string]int {
	stats := map[string]int{"total": len(legacyMonolithSymbolContracts), "route_symbols": 0, "high_risk": 0, "critical": 0}
	for _, contract := range legacyMonolithSymbolContracts {
		if contract.HasRouteDecorator {
			stats["route_symbols"]++
		}
		if contract.RiskLevel == "high" || contract.RiskLevel == "critical" {
			stats["high_risk"]++
		}
		if contract.RiskLevel == "critical" {
			stats["critical"]++
		}
	}
	return stats
}

func legacyMonolithSymbolsByReplacement(file string) []legacySymbolContract {
	out := []legacySymbolContract{}
	for _, contract := range legacyMonolithSymbolContracts {
		if contract.ReplacementFile == file {
			out = append(out, contract)
		}
	}
	return out
}

func legacyMonolithSymbolsByRisk(risk string) []legacySymbolContract {
	out := []legacySymbolContract{}
	for _, contract := range legacyMonolithSymbolContracts {
		if contract.RiskLevel == risk {
			out = append(out, contract)
		}
	}
	return out
}
